actions.script:
def capturedGroups=['CITEST_P14_GROUP_A','CITEST_P14_GROUP_B','CITEST_P14_GROUP_NA','CITEST_P14_GROUP_MISSING']
def fixtureUser=ec.user.userId?.toString()?.startsWith('CITEST_P14_USER_') || ec.user.userId == 'EX_JOHN_DOE'
def fixturePresent=ec.entity.find('zenith.erp.contacts.CustomerGroup').condition('customerGroupId','CITEST_P14_GROUP_A').disableAuthz().one()?.organizationPartyId == 'CITEST_ORG_A'
if (!fixtureUser || !fixturePresent || !capturedGroups.contains(customerGroupId) || (partyId && !partyId.startsWith('CITEST_P14_'))) {
  ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true, fixtureCheck:false]); return
}
def names=[guard:'assert#CustomerGroupAccess',members:'get#GroupMembers',update:'update#CustomerGroup',assign:'assign#CustomerGroup',remove:'remove#CustomerGroupMember']
if (!names.containsKey(operation)) { ec.web.response.setStatus(400); ec.web.sendJsonResponse([denied:true]); return }
def parameters=[customerGroupId:customerGroupId]
if (partyId) parameters.partyId=partyId
if (operation=='update') parameters.groupName=groupName
if (operation=='remove') parameters.fromDate=java.sql.Timestamp.valueOf(fromDate.replace('T',' '))
// Authorization stays enabled for the actual operation under test.
def result=ec.service.sync().name('zenith.contacts.ContactServices.'+names[operation]).parameters(parameters).call()
def denied=ec.message.hasError()
ec.message.clearErrors()
ec.web.sendJsonResponse([fixtureCheck:true,denied:denied,allowed:result?.allowed,memberCount:result?.memberCount,memberIds:(result?.members ?: []).collect{it.partyId},activeOrganization:ec.user.getPreference('ACTIVE_ORGANIZATION')])
